use super::*;
#[derive(Default)] pub(super) struct GameplayUi {pub paint:bool,pub erase:bool,pub solid:bool,pub layer:i32,pub asset:String,pub link:Option<usize>,pub positions:HashMap<(Uuid,usize),egui::Vec2>,pub atlas:[u32;3],pub auto:bool}
pub(super) fn material(ui:&mut egui::Ui,o:&mut Object,uk:bool){ui.collapsing(tr(uk,"Фізичні параметри","Physics material"),|ui|{ui.add(egui::DragValue::new(&mut o.material.gravity_scale).range(0. ..=10.).prefix("Gravity × "));ui.add(egui::DragValue::new(&mut o.material.speed).range(0. ..=2000.).prefix("Speed "));ui.add(egui::DragValue::new(&mut o.material.jump_speed).range(0. ..=2000.).prefix("Jump "));ui.add(egui::Slider::new(&mut o.material.restitution,0. ..=1.).text("Bounce"));});}
pub(super) fn tiles(ui:&mut egui::Ui,e:&mut Editor){let uk=e.uk;let g=&mut e.gameplay;ui.horizontal_wrapped(|ui|{ui.checkbox(&mut g.paint,tr(uk,"Малювати у сцені","Paint in scene"));ui.checkbox(&mut g.erase,tr(uk,"Гумка","Eraser"));ui.checkbox(&mut g.solid,tr(uk,"Колізія","Solid"));ui.add(egui::DragValue::new(&mut g.layer).prefix("Layer "));});ui.label(tr(uk,"Шлях PNG від кореня проєкту (порожній = білий тайл)","PNG path relative to project (empty = white tile)"));ui.text_edit_singleline(&mut g.asset);ui.checkbox(&mut g.auto,"4×4 autotile atlas");for (i,n) in ["Columns","Rows","Frame"].iter().enumerate(){ui.add(egui::DragValue::new(&mut g.atlas[i]).prefix(*n).range(0..=256));}ui.label(tr(uk,"ЛКМ / перетягування — малювання. Розмір = крок сітки. Ізометрія використовує координати сцени.","LMB / drag to paint. Size = grid step. Isometric mode uses world coordinates."));}
pub(super) fn paint(e:&mut Editor,pos:[f32;2]){let g=&e.gameplay;let grid=e.tools.snap.round().clamp(1.,512.) as u32;let cell=pos.map(|x|(x/grid as f32).round() as i32);if g.erase{forge_engine::erase_tile(&mut e.project,cell,grid,g.layer);}else{let sprite=if g.asset.is_empty(){None}else{if !g.asset.starts_with("assets/")||std::path::Path::new(&g.asset).components().any(|c|!matches!(c,std::path::Component::Normal(_))){e.status="Invalid tile asset path".into();return;}Some(g.asset.clone())};let id=forge_engine::paint_tile(&mut e.project,cell,grid,g.layer,sprite,g.solid);if let Some(o)=e.project.objects.iter_mut().find(|o|o.id==id){o.animation.columns=g.atlas[0].max(1);o.animation.rows=g.atlas[1].max(1);o.animation.start=g.atlas[2];o.animation.frames=1;}}if g.auto{forge_engine::autotile(&mut e.project,g.layer,grid);}}
pub(super) fn graph(ui:&mut egui::Ui,o:&mut Object,g:&mut GameplayUi){ui.horizontal_wrapped(|ui|{for n in [NodeKind::SetVariable,NodeKind::AddVariable,NodeKind::MultiplyVariable,NodeKind::IfPositive,NodeKind::Update,NodeKind::Trigger,NodeKind::IfRight,NodeKind::IfJump,NodeKind::MoveRight,NodeKind::MoveLeft,NodeKind::MoveUp,NodeKind::MoveDown,NodeKind::Jump]{if ui.small_button(format!("+ {n:?}")).clicked()&&o.graph.nodes.len()<128{o.graph.nodes.push(n);}}if ui.button("Clear").clicked(){o.graph=Default::default();g.positions.retain(|(id,_),_|*id!=o.id);g.link=None;}});ui.collapsing("Variables / parameters",|ui|{for (i,n) in o.graph.nodes.iter().enumerate(){if matches!(n,NodeKind::SetVariable|NodeKind::AddVariable|NodeKind::MultiplyVariable|NodeKind::IfPositive){let p=o.graph.params.entry(i).or_default();ui.horizontal(|ui|{ui.label(format!("{i}: {n:?}"));ui.text_edit_singleline(&mut p.variable);ui.add(egui::DragValue::new(&mut p.value));});}}});ui.label("Click OUT then IN to toggle link · drag node header · conditions gate outgoing edges");let size=egui::vec2(ui.available_width().max(300.),(ui.available_height()-5.).max(150.));let (rect,_)=ui.allocate_exact_size(size,egui::Sense::hover());let painter=ui.painter_at(rect);painter.rect_filled(rect,4.,egui::Color32::from_gray(20));let mut rects=vec![];for i in 0..o.graph.nodes.len(){let p=g.positions.entry((o.id,i)).or_insert_with(||o.pro.graph_positions.get(i).map(|p|egui::vec2(p[0],p[1])).unwrap_or_else(||egui::vec2(12.+(i%4) as f32*145.,12.+(i/4) as f32*70.)));let r=egui::Rect::from_min_size(rect.min+*p,egui::vec2(130.,52.));rects.push(r);}for [a,b] in &o.graph.edges{if let (Some(a),Some(b))=(rects.get(*a),rects.get(*b)){painter.line_segment([a.right_center()+egui::vec2(0.,12.),b.left_center()+egui::vec2(0.,12.)],egui::Stroke::new(2.,egui::Color32::LIGHT_BLUE));}}for (i,r) in rects.into_iter().enumerate(){let header=egui::Rect::from_min_max(r.min,egui::pos2(r.right(),r.top()+25.));let response=ui.interact(header,ui.id().with((o.id,i,"drag")),egui::Sense::drag());if response.dragged(){if let Some(p)=g.positions.get_mut(&(o.id,i)){*p+=ui.input(|i|i.pointer.delta());o.pro.graph_positions.resize(o.graph.nodes.len(),[12.,12.]);o.pro.graph_positions[i]=[p.x,p.y];}}painter.rect_filled(r,4.,egui::Color32::from_gray(50));painter.text(header.center(),egui::Align2::CENTER_CENTER,format!("{:?}",o.graph.nodes[i]),egui::FontId::proportional(12.),egui::Color32::WHITE);for (out,p) in [(false,r.left_center()),(true,r.right_center())]{let p=p+egui::vec2(0.,12.);let hit=ui.interact(egui::Rect::from_center_size(p,egui::vec2(22.,22.)),ui.id().with((o.id,i,out)),egui::Sense::click());painter.circle_filled(p,6.,if out&&g.link==Some(i){egui::Color32::YELLOW}else{egui::Color32::LIGHT_BLUE});if hit.clicked(){if out{g.link=Some(i);}else if let Some(a)=g.link.take(){if a!=i&&a<o.graph.nodes.len(){let edge=[a,i];if o.graph.edges.contains(&edge){o.graph.edges.retain(|e|*e!=edge);}else{o.graph.edges.push(edge);}}}}}}}
pub(super) fn components(ui:&mut egui::Ui,o:&mut Object){use forge_engine::*;ui.collapsing("Rapier collider",|ui|{let p=&mut o.pro.physics;egui::ComboBox::from_id_salt("shape").selected_text(format!("{:?}",p.shape)).show_ui(ui,|ui|{for s in [Shape::Box,Shape::Circle,Shape::Capsule]{ui.selectable_value(&mut p.shape,s,format!("{s:?}"));}});ui.add(egui::DragValue::new(&mut p.mass).range(0.001..=1000.).prefix("Mass "));ui.add(egui::Slider::new(&mut p.friction,0. ..=2.).text("Friction"));ui.checkbox(&mut p.lock_rotation,"Lock rotation");});ui.collapsing("Light",|ui|{if ui.button("Add / remove light").clicked(){o.pro.light=if o.pro.light.is_some(){None}else{Some(Light::default())};}if let Some(l)=&mut o.pro.light{ui.add(egui::DragValue::new(&mut l.radius).range(1. ..=4000.).prefix("Radius "));ui.add(egui::Slider::new(&mut l.intensity,0. ..=4.).text("Intensity"));ui.color_edit_button_rgb(&mut l.color);}});ui.collapsing("Particles",|ui|{ui.horizontal_wrapped(|ui|{for effect in [Effect::Fire,Effect::Smoke,Effect::Rain,Effect::Snow,Effect::Custom]{if ui.button(format!("{effect:?}")).clicked(){o.pro.emitter=Some(Emitter::preset(effect));}}if ui.button("Remove").clicked(){o.pro.emitter=None;}});if let Some(p)=&mut o.pro.emitter{ui.add(egui::Slider::new(&mut p.rate,1. ..=200.).text("Rate"));ui.add(egui::Slider::new(&mut p.lifetime,0.05..=10.).text("Lifetime"));ui.add(egui::DragValue::new(&mut p.size).prefix("Size "));for v in &mut p.velocity{ui.add(egui::DragValue::new(v));}ui.color_edit_button_srgba_unmultiplied(&mut p.color);}});ui.collapsing("Audio",|ui|{if ui.button("Add / remove audio").clicked(){o.pro.sound=if o.pro.sound.is_some(){None}else{Some(Sound::default())};}if let Some(s)=&mut o.pro.sound{ui.text_edit_singleline(&mut s.path);ui.checkbox(&mut s.music,"Music bus");ui.checkbox(&mut s.looping,"Loop");ui.add(egui::Slider::new(&mut s.volume,0. ..=1.).text("Volume"));}});}
pub(super) fn settings(ui:&mut egui::Ui,e:&mut Editor){let s=&mut e.project.settings;ui.checkbox(&mut s.rapier,"Rapier physics (experimental)");ui.add(egui::Slider::new(&mut s.ambient,0. ..=1.).text("Ambient"));for (name,v) in [("Master",&mut s.master),("Music",&mut s.music),("SFX",&mut s.sfx)]{ui.add(egui::Slider::new(v,0. ..=1.).text(name));}if ui.button("Add HUD button").clicked(){s.widgets.push(forge_engine::Widget::default());}let mut remove=None;for (i,w) in s.widgets.iter_mut().enumerate(){ui.push_id(i,|ui|{ui.text_edit_singleline(&mut w.text);egui::ComboBox::from_id_salt("action").selected_text(&w.action).show_ui(ui,|ui|{for a in ["left","right","jump","label"]{ui.selectable_value(&mut w.action,a.into(),a);}});for v in &mut w.anchor{ui.add(egui::Slider::new(v,0. ..=1.));}if ui.button("Remove").clicked(){remove=Some(i);}});}if let Some(i)=remove{s.widgets.remove(i);}if ui.button("Export Windows project bundle").clicked(){if let Some(path)=&e.path{if let Some(dest)=rfd::FileDialog::new().pick_folder(){e.status=match forge_engine::export_bundle(path,&dest){Ok(())=>"Bundle exported; copy ForgePlayer.exe here".into(),Err(e)=>e};}}}}

pub(super) fn production_object(ui:&mut egui::Ui,o:&mut Object){ui.collapsing("Production / Виробництво",|ui|{let mut nav=o.production.navigation.is_some();if ui.checkbox(&mut nav,"Navigation / Навігація").changed(){o.production.navigation=nav.then(Default::default);}if let Some(n)=&mut o.production.navigation{ui.checkbox(&mut n.enabled,"Enabled");for i in 0..2{ui.add(egui::DragValue::new(&mut n.target[i]).prefix(["Target X ","Target Y "][i]));}ui.add(egui::DragValue::new(&mut n.speed).range(0. ..=2000.).prefix("Speed "));ui.add(egui::DragValue::new(&mut n.grid).range(8..=256).prefix("Grid "));ui.label("Body=None; non-player NPC");}let mut tex=o.production.particle_texture.clone().unwrap_or_default();ui.label("Particle texture (assets/…)");if ui.text_edit_singleline(&mut tex).changed(){o.production.particle_texture=(!tex.is_empty()).then_some(tex);} });}
pub(super) fn production_settings(ui:&mut egui::Ui,e:&mut Editor){let chunks=forge_engine::tile_chunks(&e.project).len();ui.label(format!("Tile chunks (16×16): {chunks}"));let s=&mut e.project.settings.production;ui.collapsing("Input / Керування",|ui|{for (name,key) in [("Left",&mut s.controls.left),("Right",&mut s.controls.right),("Up",&mut s.controls.up),("Down",&mut s.controls.down)]{ui.horizontal(|ui|{ui.label(name);egui::ComboBox::from_id_salt(name).selected_text(key.as_str()).show_ui(ui,|ui|{for k in ["A","D","W","S","Left","Right","Up","Down","Space","J","L","I","K"]{ui.selectable_value(key,k.into(),k);}});});}ui.add(egui::Slider::new(&mut s.controls.deadzone,0. ..=0.9).text("Gamepad deadzone"));});ui.collapsing("Build profile / Збірка",|ui|{ui.text_edit_singleline(&mut s.package_id);for i in 0..2{ui.add(egui::DragValue::new(&mut s.resolution[i]).range(320..=3840).prefix(["Width ","Height "][i]));}});ui.collapsing("Rope joints / З'єднання",|ui|{let bodies=e.project.objects.iter().filter(|o|o.body!=Body::None&&!o.camera).map(|o|(o.id,o.name.clone())).collect::<Vec<_>>();if bodies.len()>=2&&ui.button("Add rope joint").clicked(){s.joints.push(forge_engine::DistanceJoint{a:bodies[0].0,b:bodies[1].0,length:100.});}let mut remove=None;for (i,j) in s.joints.iter_mut().enumerate(){ui.push_id(i,|ui|{for (label,id) in [("A",&mut j.a),("B",&mut j.b)]{egui::ComboBox::from_id_salt(label).selected_text(bodies.iter().find(|(x,_)|x==id).map(|(_,n)|n.as_str()).unwrap_or("Missing")).show_ui(ui,|ui|{for (x,n) in &bodies{ui.selectable_value(id,*x,n);}});}ui.add(egui::DragValue::new(&mut j.length).range(1. ..=10000.).prefix("Max length "));if ui.button("Remove").clicked(){remove=Some(i);}});}if let Some(i)=remove{s.joints.remove(i);}});}
